INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (35, 30000, 24001, 15, 1, 2, "", 0, "", 0, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (36, 40000, 91002, 1, 100, 8, "", 0, "", 0, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (37, 40001, 91002, 1, 150, 8, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 107501, "ぺコリーヌ", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (38, 40001, 91002, 2, 150, 8, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 107601, "コッコロ", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (39, 40001, 91002, 3, 150, 8, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 107801, "キャル", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40, 40001, 91002, 4, 150, 8, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 107701, "スズメ", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (41, 40001, 91002, 5, 150, 8, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 107901, "タマキ", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (42, 40001, 91002, 6, 150, 8, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 107501, "ぺコリーヌ", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (43, 40001, 91002, 7, 150, 8, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 107601, "コッコロ", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (44, 40001, 91002, 8, 150, 8, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 107801, "キャル", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (45, 40001, 91002, 9, 150, 8, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 107701, "スズメ", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (46, 40001, 91002, 10, 150, 8, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 107901, "タマキ", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (57, 40003, 91002, 1, 150, 8, "", 0, "", 0, 0);
