INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (320, 20001, 23001, 10, 20, 2, "", 0, "", 0, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (321, 40011, 24001, 1, 1, 2, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 125801, "リリ", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (322, 40011, 24001, 2, 1, 2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 126001, "クリア", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (323, 40011, 24001, 3, 1, 2, "んーと。\nこれ、あげる。\nはい", 126101, "プレシア", 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (324, 40011, 24001, 4, 1, 2, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 125801, "リリ", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (325, 40011, 24001, 5, 1, 2, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 126001, "クリア", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (326, 40011, 24001, 6, 1, 2, "お兄。\nきてくれて、うれしい", 126101, "プレシア", 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (327, 80009, 91002, 1, 100, 8, "", 0, "", 532001, 0);
